def card(task, wd):
    cols = [_hex('#3b7d4f'), _hex('#2a5fa8')]
    tiles = {}
    for code in range(16):
        b = [code >> i & 1 for i in range(4)]
        tiles[tuple(b)] = _corner_tile(*b, cols)
    rng = _rng(5)
    for _ in range(200):
        grid = rng.integers(0, 2, size=(9, 9))
        used = {(grid[y, x], grid[y, x + 1], grid[y + 1, x], grid[y + 1, x + 1]) for y in range(8) for x in range(8)}
        if len(used) == 16:
            break
    mp = np.zeros((64, 64, 3))
    for y in range(8):
        for x in range(8):
            mp[y * 8:y * 8 + 8, x * 8:x * 8 + 8] = tiles[grid[y, x], grid[y, x + 1], grid[y + 1, x], grid[y + 1, x + 1]]

    def seam(m):
        s = 0
        for y in range(8):
            for x in range(7):
                a, b = (m[y * 8:y * 8 + 8, x * 8 + 7], m[y * 8:y * 8 + 8, x * 8 + 8])
                s += float(np.abs(a - b).sum() > 0 and np.abs(a - b).mean())
        return s

    def terrain(m):
        return (m[..., 2] > 100).astype(int)
    tm = terrain(mp)
    mism = int(sum(((tm[:, x * 8 + 7] != tm[:, x * 8 + 8]).sum() for x in range(7))) + sum(((tm[y * 8 + 7] != tm[y * 8 + 8]).sum() for y in range(7))))
    naive = np.zeros_like(mp)
    keys = list(tiles)
    for y in range(8):
        for x in range(8):
            naive[y * 8:y * 8 + 8, x * 8:x * 8 + 8] = tiles[keys[rng.integers(16)]]
    tn = terrain(naive)
    mism_naive = int(sum(((tn[:, x * 8 + 7] != tn[:, x * 8 + 8]).sum() for x in range(7))) + sum(((tn[y * 8 + 7] != tn[y * 8 + 8]).sum() for y in range(7))))
    preview = np.tile(tiles[1, 1, 1, 1], (3, 3, 1))
    p_map = _save(wd / 'corner_tiles_test_map.png', np.kron(mp, np.ones((4, 4, 1))))
    p_pre = _save(wd / 'tile_3x3_preview.png', preview)
    loop_w, layers = (256, [{'depth': d, 'speed': 4 / 2 ** d, 'dark': 0.8 ** d} for d in range(3)])
    divides = all((loop_w % l['speed'] == 0 for l in layers))
    slower = all((layers[i]['speed'] > layers[i + 1]['speed'] and layers[i]['dark'] > layers[i + 1]['dark'] for i in range(2)))
    (wd / 'parallax.json').write_text(json.dumps({'loop_width': loop_w, 'layers': layers}), 'utf-8')
    return ([check('test map exercises all 16 corner transitions', len(used) == 16, len(used), 16), check('no terrain mismatch across any tile seam', mism == 0, mism, 0), check('parallax deeper layers slower and darker', slower, True, True), check('scroll step divides loop width', divides, True, True), check('negative control: random tile choice breaks seams', mism_naive > 0, mism_naive, '>0')], [p_map, p_pre, wd / 'parallax.json'])

def card(task, wd):
    themes = {'J': 'Brutalist Acid: background #BDBDB8, hero #C6FF00, small text #0A0A0A, ultra-condensed heavy sans, chrome and black rubber, concrete grain, harsh top light.', 'K': 'Retro 70s Warm: background #F3E3C3, hero #E8732C, small text #5A3A22, rounded heavy retro serif, film grain, warm sun.'}
    checks, outs = ([], [])
    for k, block in themes.items():
        c, o = _prompt_lock(wd, 'theme_' + k, block, ['Clip %d: the word moves in on beat %d.' % (i, i) for i in range(1, 6)], ['nike', 'coca-cola', 'apple'])
        checks += [dict(x, check='theme %s: %s' % (k, x['check'])) for x in c]
        outs += o
    hexes = {'J': '#C6FF00', 'K': '#E8732C'}
    checks.append(check('each lock carries its hero hex', all((hexes[k] in themes[k] for k in themes)), True, True))
    return (checks, outs)

